"""Exact hose entrypoint; original reviewed sources are mandatory for capture."""
import argparse
import hashlib
import importlib
import json
import os
from pathlib import Path

from fire_hose_delivery import segment_intersects, Point
from native_capture import capture


def check(root):
    config = json.loads((root / "config.json").read_text())
    case = config["case"]
    if config["selected_case_id"] != config["assignment_id"] + "__" + case["short_id"]:
        raise ValueError("exact hose case identity differs")
    if (config["law_id"], config["cell_id"], config["actor"]) != (
            "NRS-484B-913", "C197786", "motor_vehicle_driver"):
        raise ValueError("hose law/cell/actor identity differs")
    if (config["frame_count"], config["rate_hz"], config["duration_s"]) != (900, 20, 45):
        raise ValueError("Native capture profile differs")
    if set(config["camera_views"]) != {"overview", "approach", "reference_corner", "driver_reference"}:
        raise ValueError("four camera source views differ")
    if case["incident_purpose"] not in ("fire", "alarm", "practice"):
        raise ValueError("qualifying hose incident purpose differs")
    if case["hose_protection"] not in ("unprotected", "protected"):
        raise ValueError("hose protection case differs")
    if case["command_consent"] not in ("none", "given", "withheld"):
        raise ValueError("command consent case differs")
    if config["source_gate"] != "reviewed_original_required":
        raise ValueError("reviewed original source gate differs")
    return config


def reviewed_source(packet_path, source_root, config):
    packet_path = Path(packet_path)
    root = Path(source_root).resolve()
    packet = json.loads(packet_path.read_text())
    if packet.get("case_id") != config["selected_case_id"]:
        raise ValueError("reviewed packet exact case differs")
    if (packet.get("cell_id"), packet.get("law_id")) != ("C197786", "NRS-484B-913"):
        raise ValueError("reviewed packet law/cell differs")
    source_paths = set()
    for key in ("private_way", "hose", "incident", "official", "consent", "vehicle"):
        source = packet.get(key)
        if not isinstance(source, dict) or not source.get("path") or not source.get("sha256"):
            raise ValueError(key + " reviewed original source missing")
        path = (root / source["path"]).resolve()
        if not path.is_relative_to(root) or not path.is_file():
            raise ValueError(key + " reviewed original file unavailable")
        if hashlib.sha256(path.read_bytes()).hexdigest() != source["sha256"]:
            raise ValueError(key + " reviewed original hash mismatch")
        if path in source_paths:
            raise ValueError("distinct reviewed original sources required")
        source_paths.add(path)
        original = json.loads(path.read_text())
        expected = {field: value for field, value in source.items() if field not in ("path", "sha256")}
        if original != expected:
            raise ValueError(key + " reviewed original content mismatch")
    hose = packet["hose"]
    if hose.get("fire_department_affiliation") is not True:
        raise ValueError("fire-department hose affiliation unproven")
    if not hose.get("blueprint_id") or "hose" not in hose["blueprint_id"].lower():
        raise ValueError("hose-specific blueprint identity missing")
    if hose.get("protection") != config["case"]["hose_protection"]:
        raise ValueError("hose protection source differs")
    if packet["incident"].get("purpose") != config["case"]["incident_purpose"]:
        raise ValueError("incident purpose source differs")
    if packet["consent"].get("status") != config["case"]["command_consent"]:
        raise ValueError("official consent source differs")
    if not packet["official"].get("in_command") or not packet["official"].get("identity"):
        raise ValueError("command official source unproven")
    if packet["consent"].get("status") == "given" and (
            packet["consent"].get("official_identity") != packet["official"]["identity"]
            or packet["consent"].get("frame") is None or not packet["consent"].get("scope")):
        raise ValueError("command official consent timing or scope unproven")
    if packet["vehicle"].get("ordinary_motor_vehicle") is not True or packet["vehicle"].get("human_driver") is not True:
        raise ValueError("vehicle and human driver source unproven")
    road = packet["private_way"]
    if not road.get("owner") or not road.get("permitted_access"):
        raise ValueError("private way ownership or access unproven")
    path = road.get("ego_route_xy")
    segment = hose.get("segment_xy")
    if not isinstance(path, list) or len(path) < 2 or not isinstance(segment, list) or len(segment) != 2:
        raise ValueError("reviewed route or actual hose segment missing")
    crosses = any(segment_intersects(Point(*a), Point(*b), Point(*segment[0]), Point(*segment[1]))
                  for a, b in zip(path, path[1:]))
    if crosses != config["case"]["planned_hose_crossing"]:
        raise ValueError("reviewed route/hose geometry differs from exact case")
    return packet


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--host")
    parser.add_argument("--port", type=int)
    parser.add_argument("--output-dir", type=Path)
    parser.add_argument("--reviewed-packet", type=Path)
    parser.add_argument("--source-root", type=Path)
    args = parser.parse_args()
    config = check(Path(__file__).resolve().parent)
    if args.check:
        print(config["selected_case_id"])
        return
    packet_path = args.reviewed_packet or os.environ.get("HOSE_REVIEWED_PACKET")
    source_root = args.source_root or os.environ.get("HOSE_SOURCE_ROOT")
    if not packet_path or not source_root or not args.output_dir or not args.host or not args.port:
        raise ValueError("original reviewed packet, source root, Native server and output required")
    packet = reviewed_source(packet_path, source_root, config)
    adapter_name = os.environ.get("HOSE_NATIVE_ADAPTER", "native_adapter")
    adapter = importlib.import_module(adapter_name).create_adapter(config, args.host, args.port)
    if adapter.provenance() != "original_native":
        raise ValueError("original Native adapter provenance required")
    print(json.dumps(capture(adapter, config, packet, packet_path, source_root, args.output_dir),
                     sort_keys=True))


if __name__ == "__main__":
    main()

"""CPU-side construction and original-source checks for NRS 484B.913.

No legal outcome is computed here. The caller must supply an actual Native hose
actor or map object; a scenario flag cannot create or authenticate a hose.
"""

from __future__ import annotations

from dataclasses import dataclass
from math import hypot
from typing import Any, Mapping, Sequence


@dataclass(frozen=True)
class Point:
    x: float
    y: float


def segment_intersects(a: Point, b: Point, c: Point, d: Point) -> bool:
    """Closed segment intersection, including an endpoint touch."""
    def orient(p: Point, q: Point, r: Point) -> float:
        return (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x)

    def on(p: Point, q: Point, r: Point) -> bool:
        return min(p.x, q.x) <= r.x <= max(p.x, q.x) and min(p.y, q.y) <= r.y <= max(p.y, q.y)

    values = (orient(a, b, c), orient(a, b, d), orient(c, d, a), orient(c, d, b))
    if values[0] * values[1] < 0 and values[2] * values[3] < 0:
        return True
    return any((v == 0 and on(p, q, r)) for v, p, q, r in (
        (values[0], a, b, c), (values[1], a, b, d),
        (values[2], c, d, a), (values[3], c, d, b)))


def point_in_polygon(point: Point, corners: Sequence[Point]) -> bool:
    """Closed polygon containment, used only for physical footprint contact."""
    inside = False
    for a, b in zip(corners, (*corners[1:], corners[0])):
        if segment_intersects(a, b, point, point):
            return True
        if (a.y > point.y) != (b.y > point.y):
            x_at_y = a.x + (point.y - a.y) * (b.x - a.x) / (b.y - a.y)
            if point.x < x_at_y:
                inside = not inside
    return inside


def body_over_hose_frames(packet: Mapping[str, Any], case_id: str,
                          *, expected_frames: int = 900) -> list[int]:
    """Measure actual sampled body footprint versus original hose segment.

    This reports geometry, not whether a legal violation occurred. A complete
    original history is required; the centerline diagnostic is insufficient.
    """
    inspect_saved_hose(packet, case_id)
    rows = packet["native"]["frames"]
    if len(rows) != expected_frames:
        raise ValueError("complete original 20 Hz frame history required")
    h0, h1 = (Point(*p) for p in packet["hose"]["segment_xy"])
    hits = []
    for row in rows:
        raw = row.get("ego_body_corners_xy")
        if not isinstance(raw, list) or len(raw) < 4 or any(
                not isinstance(p, list) or len(p) != 2 for p in raw):
            raise ValueError("original ego body footprint missing")
        corners = [Point(*p) for p in raw]
        if any(segment_intersects(a, b, h0, h1)
               for a, b in zip(corners, (*corners[1:], corners[0]))) or point_in_polygon(h0, corners) or point_in_polygon(h1, corners):
            hits.append(row["frame"])
    return hits


def require_hose_source(world: Any, actor_id: int, expected_blueprint: str) -> Any:
    """Resolve the actual prop readback; never synthesize a hose by label."""
    if not expected_blueprint or "hose" not in expected_blueprint.lower():
        raise ValueError("hose blueprint identity missing")
    actor = world.get_actor(actor_id)
    if actor is None or actor.type_id != expected_blueprint:
        raise ValueError("Native hose actor readback mismatch")
    if not actor.is_alive:
        raise ValueError("Native hose actor is not alive")
    return actor


def select_hose_blueprint(world: Any, blueprint_id: str) -> Any:
    """Require a hose-specific blueprint in the local CARLA asset library."""
    if not blueprint_id or "hose" not in blueprint_id.lower():
        raise ValueError("hose-specific asset id required")
    blueprint = world.get_blueprint_library().find(blueprint_id)
    if blueprint is None or blueprint.id != blueprint_id:
        raise ValueError("hose-specific Native asset unavailable")
    return blueprint


def construct_hose(world: Any, blueprint_id: str, transform: Any) -> Any:
    """Spawn and read back the specified hose asset at its actual Native pose."""
    blueprint = select_hose_blueprint(world, blueprint_id)
    actor = world.try_spawn_actor(blueprint, transform)
    if actor is None:
        raise ValueError("Native hose spawn failed")
    return require_hose_source(world, actor.id, blueprint_id)


def inspect_saved_hose(packet: Mapping[str, Any], case_id: str) -> dict[str, Any]:
    """Reject missing source histories and report physical facts without verdicts."""
    if packet.get("case_id") != case_id:
        raise ValueError("exact case identity mismatch")
    native = packet.get("native")
    if not isinstance(native, Mapping) or not native.get("result_sha256"):
        raise ValueError("sealed Native result hash missing")
    frames = native.get("frames")
    if not isinstance(frames, Sequence) or len(frames) < 2:
        raise ValueError("original frame history missing")
    for key in ("hose", "road", "incident", "command_official", "consent", "vehicle"):
        source = packet.get(key)
        if not isinstance(source, Mapping) or not source.get("source_path") or not source.get("sha256"):
            raise ValueError(f"{key} original source binding missing")
    hose = packet["hose"]
    endpoints = hose.get("segment_xy")
    if not isinstance(endpoints, list) or len(endpoints) != 2 or any(len(p) != 2 for p in endpoints):
        raise ValueError("hose original geometry missing")
    h0, h1 = (Point(*p) for p in endpoints)
    if hypot(h1.x - h0.x, h1.y - h0.y) <= 0:
        raise ValueError("hose has zero length")
    positions = []
    last_frame = -1
    last_time = None
    for row in frames:
        if not isinstance(row, Mapping) or not isinstance(row.get("ego_xy"), list) or len(row["ego_xy"]) != 2:
            raise ValueError("original ego position missing")
        frame = row.get("frame")
        if not isinstance(frame, int) or frame <= last_frame:
            raise ValueError("original frame order invalid")
        time_seconds = row.get("elapsed_seconds")
        if not isinstance(time_seconds, (int, float)):
            raise ValueError("original elapsed-time source missing")
        if last_time is not None and (frame != last_frame + 1 or abs(time_seconds - last_time - 0.05) > 0.001):
            raise ValueError("original 20 Hz frame cadence invalid")
        last_frame = frame
        last_time = time_seconds
        positions.append(Point(*row["ego_xy"]))
    crossings = [frames[i + 1]["frame"] for i in range(len(positions) - 1)
                 if segment_intersects(positions[i], positions[i + 1], h0, h1)]
    if hose.get("fire_department_affiliation") is not True:
        raise ValueError("fire department hose affiliation unproven")
    if packet["road"].get("private_way_owner") is None or packet["road"].get("permitted_access") is None:
        raise ValueError("private way ownership or permitted access unproven")
    if packet["incident"].get("purpose") not in ("fire", "alarm", "practice"):
        raise ValueError("qualifying incident purpose unproven")
    if packet["vehicle"].get("ordinary_motor_vehicle") is not True or packet["vehicle"].get("human_driver") is not True:
        raise ValueError("vehicle or human driver identity unproven")
    official = packet["command_official"]
    if official.get("in_command") is not True or not official.get("identity"):
        raise ValueError("command official identity or status unproven")
    consent = packet["consent"]
    if consent.get("status") not in ("given", "withheld", "none"):
        raise ValueError("command-official consent status unproven")
    if consent.get("status") == "given" and (consent.get("official_identity") != official["identity"]
                                              or not consent.get("scope") or consent.get("frame") is None):
        raise ValueError("consent source, scope or timing unproven")
    if hose.get("protection") not in ("unprotected", "protected"):
        raise ValueError("hose protection arrangement unproven")
    return {"crossing_frames": crossings, "hose_protection": hose["protection"],
            "incident_purpose": packet["incident"]["purpose"], "consent_status": consent["status"],
            "consent_frame": consent.get("frame"), "official_identity": official["identity"],
            "legal_verdict": None}


def compare_saved_hose(a: Mapping[str, Any], b: Mapping[str, Any], variable: str) -> dict[str, Any]:
    """Require a controlled pair with independent sealed Native sources."""
    if variable not in ("consent", "protection", "passage", "incident_purpose"):
        raise ValueError("undeclared comparison variable")
    if a.get("native", {}).get("result_sha256") == b.get("native", {}).get("result_sha256"):
        raise ValueError("independent Native attempts required")
    a_facts = inspect_saved_hose(a, a.get("case_id"))
    b_facts = inspect_saved_hose(b, b.get("case_id"))
    keys = {"consent": "consent", "protection": "hose", "passage": "native", "incident_purpose": "incident"}
    differing = keys[variable]
    def payload(source: Mapping[str, Any]) -> dict[str, Any]:
        return {key: value for key, value in source.items() if key not in ("source_path", "sha256")}

    for key in ("road", "vehicle", "command_official"):
        left, right = payload(a.get(key, {})), payload(b.get(key, {}))
        if key == "road" and variable == "passage":
            if left.get("ego_route_xy") == right.get("ego_route_xy"):
                raise ValueError("passage route contrast absent")
            left.pop("ego_route_xy", None)
            right.pop("ego_route_xy", None)
        if left != right:
            raise ValueError(f"fixed {key} context changed")
    for key in ("hose", "incident", "consent"):
        if key != differing and payload(a.get(key, {})) != payload(b.get(key, {})):
            raise ValueError(f"fixed {key} condition changed")
    if variable == "consent" and a["consent"].get("status") == b["consent"].get("status"):
        raise ValueError("consent contrast absent")
    if variable == "protection" and a["hose"].get("protection") == b["hose"].get("protection"):
        raise ValueError("protection contrast absent")
    if variable == "incident_purpose" and a["incident"].get("purpose") == b["incident"].get("purpose"):
        raise ValueError("incident-purpose contrast absent")
    if variable == "passage" and bool(a_facts["crossing_frames"]) == bool(b_facts["crossing_frames"]):
        raise ValueError("physical-passage contrast absent")
    return {"comparison_variable": variable, "observed_a": a_facts,
            "observed_b": b_facts, "legal_verdict": None}

"""Lazy CARLA Native adapter for source-gated hose capture.

Reviewed packet poses and blueprints are mandatory. The resulting physical
motion and pixels still require independent original-source audit.
"""

import io
import math
from queue import Empty, Queue


VIEWS = ("overview", "approach", "reference_corner", "driver_reference")


def steering_to(current_xy, yaw_degrees, target_xy):
    desired = math.atan2(target_xy[1] - current_xy[1], target_xy[0] - current_xy[0])
    error = (desired - math.radians(yaw_degrees) + math.pi) % (2 * math.pi) - math.pi
    return max(-1.0, min(1.0, error / 0.7))


def body_corners(transform, extent, offset=None):
    yaw = math.radians(transform.rotation.yaw)
    c, s = math.cos(yaw), math.sin(yaw)
    x, y = transform.location.x, transform.location.y
    ox = 0.0 if offset is None else offset.x
    oy = 0.0 if offset is None else offset.y
    return [[x + dx * c - dy * s, y + dx * s + dy * c]
            for dx, dy in ((ox - extent.x, oy - extent.y),
                           (ox + extent.x, oy - extent.y),
                           (ox + extent.x, oy + extent.y),
                           (ox - extent.x, oy + extent.y))]


class Adapter:
    def __init__(self, config, host, port):
        import carla
        self.carla = carla
        self.config = config
        self.client = carla.Client(host, port)
        self.client.set_timeout(20.0)
        self.world = self.client.get_world()
        self.ego = None
        self.route = None
        self.camera_poses = None
        self.sensors = {}
        self.queues = {}
        self.pending = {}

    def provenance(self):
        return "original_native"

    def pose(self, values):
        if not isinstance(values, list) or len(values) != 4:
            raise ValueError("reviewed original [x,y,z,yaw] pose required")
        x, y, z, yaw = values
        if not all(type(v) in (int, float) and math.isfinite(v) for v in values):
            raise ValueError("reviewed original pose must be finite")
        return self.carla.Transform(self.carla.Location(x=x, y=y, z=z),
                                    self.carla.Rotation(yaw=yaw))

    def snapshot_settings(self):
        return self.world.get_settings()

    def set_synchronous(self, delta):
        settings = self.world.get_settings()
        settings.synchronous_mode = True
        settings.fixed_delta_seconds = delta
        self.world.apply_settings(settings)

    def hose_transform(self, reviewed):
        return self.pose(reviewed["hose"]["pose_xyzyaw"])

    def spawn_ego(self, vehicle, private_way):
        blueprint_id = vehicle.get("blueprint_id")
        if not blueprint_id or not blueprint_id.startswith("vehicle."):
            raise ValueError("reviewed vehicle blueprint missing")
        blueprint = self.world.get_blueprint_library().find(blueprint_id)
        if blueprint is None or blueprint.id != blueprint_id:
            raise ValueError("reviewed vehicle blueprint unavailable")
        actor = self.world.try_spawn_actor(blueprint, self.pose(vehicle["pose_xyzyaw"]))
        if actor is None or self.world.get_actor(actor.id) is None:
            raise ValueError("original ego spawn/readback failed")
        self.ego = actor
        self.camera_poses = private_way.get("camera_poses_xyzyaw")
        return actor

    def set_route(self, ego, points, crossing):
        if ego is not self.ego or not isinstance(points, list) or len(points) < 2:
            raise ValueError("reviewed original ego route missing")
        if any(not isinstance(p, list) or len(p) != 2 for p in points):
            raise ValueError("reviewed original route coordinates missing")
        self.route = [tuple(p) for p in points]
        self.waypoint = 1
        self.planned_crossing = crossing

    def start_cameras(self, views):
        if tuple(views) != VIEWS or not isinstance(self.camera_poses, dict) or set(self.camera_poses) != set(VIEWS):
            raise ValueError("reviewed original four camera poses required")
        for view in VIEWS:
            blueprint = self.world.get_blueprint_library().find("sensor.camera.rgb")
            width, height = self.config["camera_dimensions"][view]
            blueprint.set_attribute("image_size_x", str(width))
            blueprint.set_attribute("image_size_y", str(height))
            blueprint.set_attribute("sensor_tick", "0.05")
            sensor = self.world.try_spawn_actor(blueprint, self.pose(self.camera_poses[view]))
            if sensor is None or self.world.get_actor(sensor.id) is None:
                raise ValueError("original camera spawn/readback failed")
            queue = Queue()
            sensor.listen(queue.put)
            self.sensors[view] = sensor
            self.queues[view] = queue
            self.pending[view] = {}

    def tick(self):
        transform = self.ego.get_transform()
        xy = (transform.location.x, transform.location.y)
        target = self.route[self.waypoint]
        if math.dist(xy, target) < 1.5 and self.waypoint < len(self.route) - 1:
            self.waypoint += 1
            target = self.route[self.waypoint]
        finished = self.waypoint == len(self.route) - 1 and math.dist(xy, target) < 1.0
        steer = steering_to(xy, transform.rotation.yaw, target)
        self.ego.apply_control(self.carla.VehicleControl(throttle=0.0 if finished else 0.28,
                                                          steer=steer, brake=1.0 if finished else 0.0))
        frame = self.world.tick()
        snapshot = self.world.get_snapshot()
        if snapshot.frame != frame:
            raise ValueError("original world snapshot frame differs")
        return {"frame": frame, "time_s": snapshot.timestamp.elapsed_seconds}

    def observe(self, snapshot, hose):
        actor = self.world.get_actor(self.ego.id)
        actual_hose = self.world.get_actor(hose.id)
        if actor is None or actual_hose is None or not actual_hose.is_alive:
            raise ValueError("original ego or hose actor disappeared")
        transform = actor.get_transform()
        return {"ego_xy": [transform.location.x, transform.location.y],
                "ego_body_corners_xy": body_corners(transform, actor.bounding_box.extent,
                                                     actor.bounding_box.location),
                "ego_actor_id": actor.id}

    def camera_packets(self, snapshot):
        from PIL import Image
        frame = snapshot["frame"]
        packets = {}
        for view in VIEWS:
            image = self.pending[view].pop(frame, None)
            while image is None:
                try:
                    candidate = self.queues[view].get(timeout=10.0)
                except Empty as exc:
                    raise ValueError("original camera source timed out") from exc
                if candidate.frame == frame:
                    image = candidate
                elif candidate.frame > frame:
                    self.pending[view][candidate.frame] = candidate
                else:
                    raise ValueError("stale original camera frame")
            rgba = Image.frombytes("RGBA", (image.width, image.height),
                                   bytes(image.raw_data), "raw", "BGRA")
            stream = io.BytesIO()
            rgba.convert("RGB").save(stream, format="PNG")
            packets[view] = {"frame": image.frame, "time_s": image.timestamp,
                             "sensor_id": self.sensors[view].id, "width": image.width,
                             "height": image.height, "png": stream.getvalue()}
        return packets

    def stop_cameras(self):
        for sensor in self.sensors.values():
            try:
                sensor.stop()
            finally:
                sensor.destroy()
        self.sensors.clear()

    def destroy(self, actor):
        actor.destroy()

    def restore_settings(self, settings):
        self.world.apply_settings(settings)


def create_adapter(config, host, port):
    return Adapter(config, host, port)
